ll lcm_cap(ll a, ll b, ll cap){      // cap = m+1
    ll g = gcd(a,b);
    ll x = a/g;                      // divide FIRST: (a/g)*b < (a*b)/g, less overflow
    if(x > cap/b) return cap;        // would x*b exceed cap? check BEFORE multiplying
    ll r = x*b;
    return r > cap ? cap : r;
}
